#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;
int minimumMerges(const vector<int>& values) {
    int n = static_cast<int>(values.size()), total = 0;
    for (int value : values) total += value;
    if (total == 0) return 0;
    int largest = *max_element(values.begin(), values.end());
    for (int groups = n; groups >= 1; --groups) {
        if (total % groups != 0) continue;
        int target = total / groups;
        if (target < largest) continue;
        int partial = 0;
        bool possible = true;
        for (int value : values) {
            partial += value;
            if (partial > target) { possible = false; break; }
            if (partial == target) partial = 0;
        }
        if (possible && partial == 0) return n - groups;
    }
    return n - 1;
}
void solve(istream& in, ostream& out) {
    int tests;
    in >> tests;
    while (tests--) {
        int n;
        in >> n;
        vector<int> values(n);
        for (int& value : values) in >> value;
        out << minimumMerges(values) << '\n';
    }
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve(cin, cout);
    return 0;
}
