bool spellable(const array<string, 4>& blocks, const string& word) {
    array<int, 4> order = {{0, 1, 2, 3}};
    do {
        bool possible = true;
        for (int i = 0; i < static_cast<int>(word.size()); ++i)
            if (blocks[order[i]].find(word[i]) == string::npos) possible = false;
        if (possible) return true;
    } while (next_permutation(order.begin(), order.end()));
    return false;
}
void solve(istream& in, ostream& out) {
    int words;
    in >> words;
    array<string, 4> blocks;
    for (string& block : blocks) in >> block;
    while (words--) {
        string word;
        in >> word;
        out << (spellable(blocks, word) ? "YES" : "NO") << '\n';
    }
}
